dtsPropsFor.Accordion:
/** Compound namespace: compose as Accordion.Root > Accordion.Item > Accordion.Header > Accordion.Trigger + Accordion.Panel. These are the Root props; Item takes `value` and `disabled`. */
  /** Open item values. Always an array, including in single-expansion mode. */
  value?: (string | number)[];
  /** Initially open item values. Always an array, even when `multiple` is false. */
  defaultValue?: (string | number)[];
  onValueChange?: (value: (string | number)[]) => void;
  /** Allow more than one section open at a time. Defaults to false. */
  multiple?: boolean;
  disabled?: boolean;
  /** Keep panel content mounted while closed, for find-in-page and SEO. */
  keepMounted?: boolean;
  orientation?: "horizontal" | "vertical";
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Collapsible:
/** Compound namespace: compose as Collapsible.Root > Collapsible.Trigger + Collapsible.Panel. These are the Root props. An empty Root renders an empty box — it needs a Trigger and a Panel. */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Details:
/** Compound namespace over the native details/summary elements: compose as Details.Root > Details.Summary + Details.Content. Summary must come first. These are the Root props — it accepts every native <details> prop. */
  open?: boolean;
  onToggle?: React.ReactEventHandler<HTMLDetailsElement>;
  /** Native exclusive-accordion grouping name. */
  name?: string;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.SearchSelect:
/** Compound namespace: compose as SearchSelect.Root > SearchSelect.Trigger (with SearchSelect.Value) > SearchSelect.Popup > SearchSelect.Input + SearchSelect.List. `SearchSelect` is a namespace object, not a renderable component. Render SearchSelect.Root; put Popup inside Portal and Positioner. These are the Root props. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  name?: string;
  className?: string;
  children?: React.ReactNode;
